package cn.course.community;
import java.util.*;
import java.time.Instant;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:assignmentmanagement;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","app.seed=true","app.seed-password=TestOnly!2026Long"})
@AutoConfigureMockMvc @Transactional
class AssignmentManagementTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired Store s;@Autowired CommunityService domain;@Autowired AssignmentManagement management;
 long teacher(){return s.uid("teacher@example.test");}
 AssignmentManagement.Edit edit(int rev){return new AssignmentManagement.Edit("修订后的任务","新的任务要求",Instant.now().plusSeconds(7200).toString(),null,null,"课堂讨论后调整",rev);}
 AssignmentManagement.State state(String action,int rev){return new AssignmentManagement.State(action,"教学安排调整",rev);}
 long notes(){return s.db.queryForObject("SELECT COUNT(*) FROM notification",Long.class);}
 long task(){return domain.createAssignment(1,"管理验收任务","提交测试",Instant.now().plusSeconds(7200).toString(),false,teacher()).get("id") instanceof Number n?n.longValue():0;}
 @Test void editIsVersionedAndPreservesBeforeAfter() {var before=domain.assignment(1);var after=management.edit(1,teacher(),edit(0));assertEquals(1,after.get("management_revision"));var h=management.history(1,teacher());assertEquals(1,h.size());JsonNode old=(JsonNode)h.getFirst().get("before"),next=(JsonNode)h.getFirst().get("after");assertEquals(before.get("title"),old.path("title").asText());assertEquals("修订后的任务",next.path("title").asText());assertEquals("课堂讨论后调整",h.getFirst().get("reason"));}
 @Test void onlyCurrentTeacherCanEditStateOrReadHistory()throws Exception {s.db.update("UPDATE course_member SET role='ASSISTANT' WHERE course_id=1 AND user_id=?",s.uid("peer@example.test"));for(String name:List.of("student","peer","outsider")){mvc.perform(put("/api/assignments/1").with(user(name+"@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(edit(0)))).andExpect(status().isForbidden());mvc.perform(post("/api/assignments/1/state").with(user(name+"@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(state("CLOSE",0)))).andExpect(status().isForbidden());mvc.perform(get("/api/assignments/1/history").with(user(name+"@example.test"))).andExpect(status().isForbidden());}}
 @Test void loginAndCsrfAreRequired()throws Exception {mvc.perform(get("/api/assignments/1/history")).andExpect(status().isUnauthorized());mvc.perform(put("/api/assignments/1").with(user("teacher@example.test")).contentType("application/json").content(json.writeValueAsString(edit(0)))).andExpect(status().isForbidden());mvc.perform(post("/api/assignments/1/state").with(user("teacher@example.test")).contentType("application/json").content(json.writeValueAsString(state("CLOSE",0)))).andExpect(status().isForbidden());}
 @Test void staleTeacherCannotOverwriteOrCloseUpdatedRules()throws Exception {management.edit(1,teacher(),edit(0));mvc.perform(put("/api/assignments/1").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(edit(0)))).andExpect(status().isConflict());mvc.perform(post("/api/assignments/1/state").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(state("CLOSE",0)))).andExpect(status().isConflict());assertEquals(1,management.history(1,teacher()).size());}
 @Test void closeStopsNewStartsAndSubmissionsButNotExistingDrafts()throws Exception {long aid=task(),student=s.uid("student@example.test");var e=domain.start(aid,student);long eid=s.id(e,"id");management.state(aid,teacher(),state("CLOSE",0));assertEquals(eid,s.id(domain.start(aid,student),"id"));domain.save(eid,new ApiController.DraftRequest("结束后保存",(JsonNode)e.get("content"),0,List.of()),student);assertEquals("结束后保存",domain.getEntry(eid,student).get("title"));mvc.perform(post("/api/assignments/"+aid+"/entries").with(user("peer@example.test")).with(csrf())).andExpect(status().isUnprocessableEntity());mvc.perform(post("/api/entries/"+eid+"/submissions").with(user("student@example.test")).with(csrf()).header("Idempotency-Key","closed-task-submission").contentType("application/json").content("{\"revision\":1}")).andExpect(status().isUnprocessableEntity());}
 @Test void idempotentSuccessfulSubmissionStillReturnsAfterManualClose()throws Exception {management.state(1,teacher(),state("CLOSE",0));mvc.perform(post("/api/entries/1/submissions").with(user("student@example.test")).with(csrf()).header("Idempotency-Key","seed-version-one").contentType("application/json").content("{\"revision\":0}")).andExpect(status().isOk());}
 @Test void extendingManualClosedTaskDoesNotReopenIt() {management.state(1,teacher(),state("CLOSE",0));var a=management.edit(1,teacher(),edit(1));assertEquals(true,a.get("manually_closed"));a=management.state(1,teacher(),state("REOPEN",2));assertEquals(false,a.get("manually_closed"));assertEquals(3,a.get("management_revision"));assertEquals(3,management.history(1,teacher()).size());}
 @Test void expiredClosedTaskRequiresExtensionBeforeReopen()throws Exception {management.state(1,teacher(),state("CLOSE",0));s.db.update("UPDATE assignment SET due_at=? WHERE id=1",Instant.now().minusSeconds(60).toString());mvc.perform(post("/api/assignments/1/state").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(state("REOPEN",1)))).andExpect(status().isUnprocessableEntity());assertEquals(1,management.history(1,teacher()).size());}
 @Test void extendingNaturalExpiryAllowsNewWork() {long aid=task();s.db.update("UPDATE assignment SET due_at=? WHERE id=?",Instant.now().minusSeconds(60).toString(),aid);management.edit(aid,teacher(),edit(0));assertNotNull(domain.start(aid,s.uid("student@example.test")));}
 @Test void duplicateCloseDoesNotCreateHistoryOrNotification()throws Exception {management.state(1,teacher(),state("CLOSE",0));long count=notes();mvc.perform(post("/api/assignments/1/state").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(state("CLOSE",1)))).andExpect(status().isUnprocessableEntity());assertEquals(count,notes());assertEquals(1,management.history(1,teacher()).size());}
 @Test void invalidOrPastDeadlineRejectedWithoutChanges()throws Exception {for(String due:List.of("wrong",Instant.now().minusSeconds(10).toString()))mvc.perform(put("/api/assignments/1").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(new AssignmentManagement.Edit("题目","要求",due,null,null,"修改原因",0)))).andExpect(status().isUnprocessableEntity());assertEquals(0,management.history(1,teacher()).size());}
 @Test void blankReasonAndInvalidStateRejected()throws Exception {mvc.perform(post("/api/assignments/1/state").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content("{\"action\":\"DELETE\",\"reason\":\" \",\"revision\":0}")).andExpect(status().isBadRequest());assertEquals(0,management.history(1,teacher()).size());}
 @Test void noOpEditRejected()throws Exception {var a=domain.assignment(1);mvc.perform(put("/api/assignments/1").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(new AssignmentManagement.Edit((String)a.get("title"),(String)a.get("requirements"),(String)a.get("due_at"),null,null,"无变化",0)))).andExpect(status().isUnprocessableEntity());}
 @Test void notificationsContainGenericMetadataAndOnlyCurrentMembers() {long n=notes();management.edit(1,teacher(),edit(0));assertEquals(n+2,notes());var alerts=s.db.queryForList("SELECT * FROM notification WHERE kind='ASSIGNMENT_CHANGE'");assertEquals(2,alerts.size());for(var a:alerts){assertEquals("assignment",a.get("target_type"));assertNotEquals(teacher(),s.id(a,"recipient_id"));assertFalse(a.toString().contains("课堂讨论后调整"));}}
 @Test void frozenSubmissionKeepsRuleSnapshotAcrossLaterEdits() {long aid=task(),uid=s.uid("student@example.test");management.edit(aid,teacher(),edit(0));var e=domain.start(aid,uid);long eid=s.id(e,"id");JsonNode doc=json.createObjectNode().put("type","doc").set("content",json.createArrayNode().add(json.createObjectNode().put("type","paragraph").set("attrs",json.createObjectNode().put("blockId","task-test"))).add(json.createObjectNode().put("type","paragraph").set("attrs",json.createObjectNode().put("blockId","task-text"))));((com.fasterxml.jackson.databind.node.ObjectNode)doc.path("content").get(1)).set("content",json.createArrayNode().add(json.createObjectNode().put("type","text").put("text","非空正文")));domain.save(eid,new ApiController.DraftRequest("快照测试",doc,0,List.of()),uid);var v=domain.submit(eid,1,"snapshot-version-test",uid);long sid=s.id(v,"id");management.edit(aid,teacher(),new AssignmentManagement.Edit("之后的题目","之后的要求",Instant.now().plusSeconds(9000).toString(),null,null,"再次修改",1));JsonNode snapshot=(JsonNode)domain.getSubmission(sid,uid).get("assignmentSnapshot");assertEquals("修订后的任务",snapshot.path("title").asText());assertEquals("新的任务要求",snapshot.path("requirements").asText());assertEquals(1,snapshot.path("management_revision").asInt());}
 @Test void legacySubmissionDoesNotInventRuleSnapshot()throws Exception {s.db.update("UPDATE submission SET assignment_snapshot_json=NULL WHERE id=1");mvc.perform(get("/api/submissions/1").with(user("student@example.test"))).andExpect(jsonPath("assignmentSnapshot").isEmpty());}
 @Test void listStatusIncludesManualClosure()throws Exception {management.state(1,teacher(),state("CLOSE",0));mvc.perform(get("/api/courses/1/assignments").with(user("student@example.test"))).andExpect(jsonPath("[0].due_status").value("CLOSED")).andExpect(jsonPath("[0].manually_closed").value(true));}
}
